def clean(self, queued=False, failed=False, success=False, all=False):
    """Clean experiments queue.

    Args:
        queued: Clean queued experiments.
        failed: Clean failed experiments.
        success: Clean successful experiments.
        all: Clean all experiments (equivalent to queued=True, failed=True, success=True).
    """
    if all:
        queued = failed = success = True

    return self.celery_queue.clear(queued=queued, failed=failed, success=success)
